import re

def parse_duration(s: str) -> int:
    total = 0
    # Match optional hours, minutes, and seconds in order
    m = re.match(r'(\d+h)?(\d+m)?(\d+s)?', s)
    if m:
        if m.group(1):
            total += int(m.group(1)[:-1]) * 3600
        if m.group(2):
            total += int(m.group(2)[:-1]) * 60
        if m.group(3):
            total += int(m.group(3)[:-1])
    return total
