from typing import List

def spiral_order(m: List[List[int]]) -> List[int]:
    if not m or not m[0]:
        return []

    res: List[int] = []
    top, bottom = 0, len(m) - 1
    left, right = 0, len(m[0]) - 1

    while top <= bottom and left <= right:
        # Traverse right
        for i in range(left, right + 1):
            res.append(m[top][i])
        top += 1

        # Traverse down
        for i in range(top, bottom + 1):
            res.append(m[i][right])
        right -= 1

        # Traverse left (if still in bounds)
        if top <= bottom:
            for i in range(right, left - 1, -1):
                res.append(m[bottom][i])
            bottom -= 1

        # Traverse up (if still in bounds)
        if left <= right:
            for i in range(bottom, top - 1, -1):
                res.append(m[i][left])
            left += 1

    return res
