def int_to_words(n: int) -> str:
    if n == 0:
        return "zero"

    ones = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    def convert_chunk(num: int) -> str:
        """Convert a number 0-999 to words."""
        if num == 0:
            return ""
        parts = []
        hundreds = num // 100
        remainder = num % 100
        if hundreds > 0:
            parts.append(f"{ones[hundreds]} hundred")
        if remainder > 0:
            if remainder < 10:
                parts.append(ones[remainder])
            elif remainder < 20:
                parts.append(teens[remainder - 10])
            else:
                t = remainder // 10
                o = remainder % 10
                if o == 0:
                    parts.append(tens[t])
                else:
                    parts.append(f"{tens[t]}-{ones[o]}")
        return " ".join(parts)

    # Break n into groups of three digits (millions, thousands, ones)
    million = n // 1_000_000
    thousand = (n % 1_000_000) // 1_000
    ones_part = n % 1_000

    words = []
    if million > 0:
        words.append(f"{convert_chunk(million)} million")
    if thousand > 0:
        words.append(f"{convert_chunk(thousand)} thousand")
    if ones_part > 0:
        words.append(convert_chunk(ones_part))

    return " ".join(words)
