def flatten_json(obj: dict) -> dict:
    result: dict = {}

    def _flatten(current, path_parts):
        if isinstance(current, dict):
            if not current:
                # Empty dict: keep as value at current path
                key = '.'.join(path_parts)
                result[key] = current
            else:
                for k, v in current.items():
                    _flatten(v, path_parts + [k])
        elif isinstance(current, list):
            if not current:
                # Empty list: keep as value at current path
                key = '.'.join(path_parts)
                result[key] = current
            else:
                for i, v in enumerate(current):
                    _flatten(v, path_parts + [str(i)])
        else:
            # Leaf value (number, string, bool, None)
            key = '.'.join(path_parts)
            result[key] = current

    _flatten(obj, [])
    return result
